1	#include "World.hpp"
2	
3	#include <algorithm>
4	#include <random>
5	
6	namespace llm_npc {
7	
8	World::World(City city)
9	    : city_(std::move(city)),
10	      rng_(std::random_device{}()) {}
11	
12	bool World::playerAttack(const Vec3& aimDirection) {
13	    if (player_.attackCooldown > 0.f) return false;
14	
15	    const WeaponDef& def = weaponDef(player_.weapon);
16	
17	    if (player_.weapon == WeaponKind::Fist) {
18	        const int target = nearestNpcWithin(player_.position, def.range);
19	        player_.attackCooldown    = def.fireCooldown;
20	        player_.attackAnimFraction = 1.0f;
21	        if (target < 0) return true;  // swing missed — cooldown still consumed
22	        npcs_[static_cast<std::size_t>(target)].takeDamage(def.damage);
23	        return true;
24	    }
25	
26	    // Pistol: check ammo, spawn a projectile.
27	    auto& ammoSlot = player_.ammo[static_cast<std::uint8_t>(player_.weapon)];
28	    if (ammoSlot <= 0) return false;
29	
30	    --ammoSlot;
31	    player_.attackCooldown    = def.fireCooldown;
32	    player_.attackAnimFraction = 1.0f;
33	
34	    // Fire along the full 3D aim (issue #91): keep the y component instead of
35	    // flattening it, and spawn from eye height so the shot leaves from the
36	    // point the player is looking through. tickProjectiles integrates the
37	    // direction in 3D and the [0,kNpcHeight] band test still catches hits.
38	    const Vec3 dir = normalize(aimDirection);
39	    Projectile p;
40	    p.position   = player_.position + Vec3{0.f, kEyeHeight, 0.f};
41	    p.direction  = dir;
42	    p.speed      = 40.f;
43	    p.damage     = def.damage;
44	    p.fromPlayer = true;
45	    projectiles_.push_back(p);
46	    return true;
47	}
48	
49	void World::playerSwitchWeapon(WeaponKind kind) {
50	    if (weaponDef(kind).ammoMax > 0) {
51	        const auto it = player_.ammo.find(static_cast<std::uint8_t>(kind));
52	        if (it == player_.ammo.end() || it->second == 0) return;
53	    }
54	    player_.weapon = kind;
55	}
56	
57	CombatFrameResult World::updateCombat(float dt) {
58	    CombatFrameResult result;
59	    tickCooldowns(dt);
60	    tickProjectiles(dt, result);
61	    tickNpcAi(dt, result);
62	    return result;
63	}
64	
65	void World::tickProjectiles(float dt, CombatFrameResult& out) {
66	    static constexpr float kNpcRadius = 0.4f;
67	    static constexpr float kNpcHeight = 1.8f;
68	
69	    for (auto& proj : projectiles_) {
70	        proj.position += proj.direction * (proj.speed * dt);
71	        proj.lifetime += dt;
72	    }
73	
74	    auto it = projectiles_.begin();
75	    while (it != projectiles_.end()) {
76	        if (it->lifetime >= it->maxLifetime) {
77	            it = projectiles_.erase(it);
78	            continue;
79	        }
