130	    } else if (page_ == Page::Creator) {
131	        // Left column: persona text fields (label drawn above each box).
132	        const float fieldX = w * 0.07f;
133	        float y = h * 0.26f;
134	        for (int f = 1; f <= 3; ++f) {
135	            hits.push_back({Rectangle{fieldX, y, w * 0.34f, 44.f}, kIdFieldBase + f});
136	            y += 92.f;
137	        }
138	        // Right column: a [<] label [>] row per category, then palette,
139	        // then the action buttons. The preview renders in-world between
140	        // the columns (main.cpp draws it while this page is open).
141	        const float rowX = w * 0.62f;
142	        const float rowW = w * 0.31f;
143	        y = h * 0.26f;
144	        for (int c = 0; c < kPartCategoryCount; ++c) {
145	            hits.push_back({Rectangle{rowX, y, 44.f, 40.f}, kIdPartPrev + c});
146	            hits.push_back({Rectangle{rowX + rowW - 44.f, y, 44.f, 40.f}, kIdPartNext + c});
147	            y += 56.f;
148	        }
149	        hits.push_back({Rectangle{rowX, y, rowW, 40.f}, kIdPalette});
150	        y += 64.f;
151	        hits.push_back({Rectangle{rowX, y, rowW * 0.47f, 48.f}, kIdRandomize});
152	        hits.push_back(
153	            {Rectangle{rowX + rowW * 0.53f, y, rowW * 0.47f, 48.f}, kIdCreate});
154	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, h * 0.86f, 320.f, 48.f}, kIdBack});
155	    } else if (page_ == Page::Multiplayer) {
156	        const float x = (w - 420.f) * 0.5f;
157	        float y = h * 0.30f;
158	        if (multiplayer_.active && multiplayer_.active()) {
159	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdLeave});
160	            y += 72.f;
161	        } else {
162	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdHost});
163	            y += 88.f;
164	            hits.push_back({Rectangle{x, y, 420.f, 44.f}, kIdAddress});
165	            y += 60.f;
166	            hits.push_back({Rectangle{x, y, 420.f, 52.f}, kIdJoin});
167	            y += 72.f;
168	        }
169	        hits.push_back({Rectangle{(w - 320.f) * 0.5f, y + 24.f, 320.f, 52.f}, kIdBack});
170	    } else {
171	        float y = h * 0.24f;
172	        for (std::size_t i = 0; i < kActionCount; ++i) {
173	            hits.push_back({Rectangle{w * 0.5f + 90.f, y, 180.f, 40.f},
174	                            kIdChipBase + static_cast<int>(i)});
